fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n, "vals_2 must have the same length as vals_1");
    assert_eq!(conds_1.len(), n, "conds_1 must have the same length as vals_1");
    assert_eq!(conds_2.len(), n, "conds_2 must have the same length as vals_1");

    // Prepare the output vector to hold exactly n elements.
    avgs.clear();
    avgs.reserve(n);

    for i in 0..n {
        let out = match (conds_1[i], conds_2[i]) {
            (true, true) => {
                // both true: integer average
                (vals_1[i] + vals_2[i]) / 2
            }
            (true, false) => {
                // only first is true
                vals_1[i]
            }
            (false, true) => {
                // only second is true
                vals_2[i]
            }
            (false, false) => {
                // by assumption this cannot happen
                unreachable!("At least one condition must be true at index {}", i)
            }
        };
        avgs.push(out);
    }
}